	/** Records each waiting step and publishes the signal at a chosen step, so tier transitions are deterministic. */
	private static final class RecordingWaiter implements AsyncSignal.Waiter {
		private AsyncSignal signal;
		private final String signalAt;
		private final int signalAfter;
		int spins;
		int yields;
		int parks;

		RecordingWaiter(String signalAt, int signalAfter) {
			this.signalAt = signalAt;
			this.signalAfter = signalAfter;
		}

		@Override
		public void spin() {
			spins++;
			maybeSignal("spin", spins);
		}

		@Override
		public void yield() {
			yields++;
			maybeSignal("yield", yields);
		}

		@Override
		public void park(Object blocker) {
			parks++;
			maybeSignal("park", parks);
		}

		@Override
		public void parkNanos(Object blocker, long nanos) {
			park(blocker);
		}

		private void maybeSignal(String step, int count) {
			if (step.equals(signalAt) && count == signalAfter) {
				signal.signal();
			}
		}
	}

	private static RecordingWaiter awaitWith(RecordingWaiter waiter) throws InterruptedException {
		AsyncSignal signal = new AsyncSignal(waiter);
		waiter.signal = signal;
		long observed = signal.sequence();
		boolean primary = signal.register();
		try {
			signal.awaitRegistered(observed, Long.MAX_VALUE);
		} finally {
			signal.unregister(primary);
		}
		assertEquals(observed + 1, signal.sequence());
		return waiter;
	}

